import { assign, IS_NON_DIMENSIONAL } from '../util';
import options from '../options';

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	let i;

	for (i in oldProps) {
		if (i !== 'children' && i !== 'key' && !(i in newProps)) {
			setProperty(dom, i, null, oldProps[i], isSvg);
		}
	}

	for (i in newProps) {
		if (
			(!hydrate || typeof newProps[i] == 'function') &&
			i !== 'children' &&
			i !== 'key' &&
			i !== 'value' &&
			i !== 'checked' &&
			oldProps[i] !== newProps[i]
		) {
			setProperty(dom, i, newProps[i], oldProps[i], isSvg);
		}
	}
}

/**
 * Set a property value on a DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	let useCapture;
	let style;
	let styleKey;
	let styleValue;
	let prevStyle;
	let nextStyle;
	let cssText;
	let strippedEventName;
	let lowerCasedEvent;
	let builtinType;
	let customType;
	let listenerMap;
	let listenerKey;
	let handler;
	let nextDomValue;
	let ariaPrefix;
	let keepRawStyle;
	let numericStyle;

	o: if (name === 'style') {
		style = dom.style;
		if (typeof value == 'string') {
			cssText = value;
			style.cssText = cssText;
		} else {
			if (typeof oldValue == 'string') {
				cssText = '';
				style.cssText = cssText;
				oldValue = cssText;
			}

			if (oldValue) {
				prevStyle = assign({}, oldValue);
				for (styleKey in prevStyle) {
					if (!(value && styleKey in value)) {
						styleValue = '';
						style[styleKey] = styleValue;
						style.setProperty(styleKey, styleValue);
					}
				}
			}

			if (value) {
				nextStyle = assign({}, value);
				for (styleKey in nextStyle) {
					styleValue = nextStyle[styleKey];
					if (!oldValue || styleValue !== oldValue[styleKey]) {
						numericStyle = typeof styleValue == 'number';
						keepRawStyle = IS_NON_DIMENSIONAL.test(styleKey);
						let customStyle = styleKey[0] === '-';
						let normalizedStyle =
							styleValue == null
								? ''
								: numericStyle && !keepRawStyle
								? styleValue + 'px'
								: styleValue;
						if (customStyle) {
							style.setProperty(styleKey, styleValue);
						}
						if (!customStyle) {
							style[styleKey] = normalizedStyle;
						}
					}
				}
			}
		}
	} else if (name[0] === 'o' && name[1] === 'n') {
		useCapture = name !== (name = name.replace(/Capture$/, ''));
		strippedEventName = name;
		lowerCasedEvent = strippedEventName.toLowerCase();
		builtinType = lowerCasedEvent.slice(2);
		customType = strippedEventName.slice(2);
		if (lowerCasedEvent in dom) name = builtinType;
		else name = customType;

		listenerMap = dom._listeners;
		if (!listenerMap) {
			listenerMap = {};
			dom._listeners = listenerMap;
		}
		listenerKey = name + useCapture;
		listenerMap[listenerKey] = value;
		handler = useCapture ? eventProxyCapture : eventProxy;
		let eventType = name;
		let eventCapture = useCapture;
		let eventHandler = handler;

		if (value) {
			if (!oldValue) {
				dom.addEventListener(eventType, eventHandler, eventCapture);
			}
		} else {
			dom.removeEventListener(eventType, eventHandler, eventCapture);
		}
	} else if (name !== 'dangerouslySetInnerHTML') {
		if (isSvg) {
			// Normalize incorrect prop usage for SVG:
			// - xlink:href / xlinkHref --> href (xlink:href was removed from SVG and isn't needed)
			// - className --> class
			name = name.replace(/xlink[H:h]/, 'h').replace(/sName$/, 's');
		} else if (
			name !== 'href' &&
			name !== 'list' &&
			name !== 'form' &&
			// Default value in browsers is `-1` and an empty string is
			// cast to `0` instead
			name !== 'tabIndex' &&
			name !== 'download' &&
			name in dom
		) {
			try {
				nextDomValue = value == null ? '' : value;
				let propertyName = name;
				let propertyTarget = dom;
				propertyTarget[propertyName] = nextDomValue;
				// labelled break is 1b smaller here than a return statement (sorry)
				break o;
			} catch (e) {}
		}

		ariaPrefix = name.indexOf('ar') === 0;
		if (typeof value === 'function') {
			// never serialize functions as attribute values
		} else if (
			value != null &&
			(value !== false || ariaPrefix)
		) {
			let attrName = name;
			let attrValue = value;
			dom.setAttribute(attrName, attrValue);
		} else {
			dom.removeAttribute(name);
		}
	}
}

/**
 * Proxy an event to hooked event handlers
 * @param {Event} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	this._listeners[e.type + false](options.event ? options.event(e) : e);
}

function eventProxyCapture(e) {
	this._listeners[e.type + true](options.event ? options.event(e) : e);
}

